// Use built-in https module for HTTP requests
const https = require('https');

// Function to make POST request
function postAuditData(data, callback) {
  const options = {
    hostname: 'localhost',
    port: 47301,
    path: '/api/audit',
    method: 'POST',
    headers: {
      'Content-Type': 'application/json',
      'Content-Length': Buffer.byteLength(JSON.stringify(data))
    }
  };

  const req = https.request(options, (res) => {
    let responseData = '';
    res.on('data', (chunk) => {
      responseData += chunk;
    });
    res.on('end', () => {
      callback(null, res.statusCode, responseData);
    });
  });

  req.on('error', (error) => {
    callback(error);
  });

  req.write(JSON.stringify(data));
  req.end();
}

