const fs = require('fs');
const path = require('path');

// Directory containing migration files
const MIGRATIONS_DIR = './migrations';

// Function to read and sort migration files
function getMigrationFiles() {
  try {
    // Read all files from the migrations directory
    const files = fs.readdirSync(MIGRATIONS_DIR);

    // Filter only .sql files and sort them alphabetically
    return files
      .filter(file => path.extname(file).toLowerCase() === '.sql')
      .sort();
  } catch (error) {
    console.error('Error reading migration directory:', error.message);
    process.exit(1);
  }
}

// Main migration function
async function runMigrations() {
  const migrationFiles = getMigrationFiles();

  if (migrationFiles.length === 0) {
    console.log('No migration files found in', MIGRATIONS_DIR);
    return;
  }

  console.log('Starting database migrations...');

  for (const file of migrationFiles) {
    const filePath = path.join(MIGRATIONS_DIR, file);
    console.log(`Applying migration: ${filePath}`);

    // In a real scenario, you would read and execute the SQL file against the database here
    // await executeSqlFile(filePath);
  }

  console.log('All migrations applied successfully.');
}

// Run the migrations
runMigrations().catch(err => {
  console.error('Migration failed:', err.message);
  process.exit(1);
});

